package com.returnright.service;

import java.util.Optional;

/**
 * Where return photo bytes are kept. Keys are generated by the server, e.g. {@code
 * returns/<returnId>/<photoId>.jpg}.
 */
public interface PhotoStorage {

  void store(String key, byte[] content);

  /** The photo's bytes, or empty if nothing is stored under the key. */
  Optional<byte[]> load(String key);

  /** Removes the photo; does nothing if it is not there. */
  void delete(String key);
}
